package io.github.borderarea01.znote;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import java.io.*;import java.net.*;import org.json.*;

/** Controlled slow/lost replies, real :capture windows and foreground service. */
final class BackgroundSubmitSmoke {
 final Instrumentation test;final Context c;final UiAutomation ui;
 BackgroundSubmitSmoke(Instrumentation t){test=t;c=t.getTargetContext();ui=t.getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(info);}
 void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 byte[] all(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
 String shell(String value)throws Exception{try(ParcelFileDescriptor fd=ui.executeShellCommand(value);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){return new String(all(in),java.nio.charset.StandardCharsets.UTF_8);}}
 JSONObject control(String mode)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL("http://10.0.2.2:3751/test/control"+(mode.isEmpty()?"":"?mode="+mode)).openConnection(Proxy.NO_PROXY);try(InputStream in=connection.getInputStream()){return new JSONObject(new String(all(in),java.nio.charset.StandardCharsets.UTF_8));}finally{connection.disconnect();}}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String value){if(n==null)return null;if(n.isVisibleToUser()&&(value.equals(String.valueOf(n.getText()))||value.equals(String.valueOf(n.getContentDescription()))))return AccessibilityNodeInfo.obtain(n);for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child==null)continue;AccessibilityNodeInfo result=find(child,value);child.recycle();if(result!=null)return result;}return null;}
 AccessibilityNodeInfo node(String value,long wait)throws Exception{long end=SystemClock.uptimeMillis()+wait;do{for(AccessibilityWindowInfo w:ui.getWindows()){AccessibilityNodeInfo root=w.getRoot(),hit=find(root,value);if(root!=null)root.recycle();if(hit!=null)return hit;}Thread.sleep(60);}while(SystemClock.uptimeMillis()<end);throw new AssertionError("Missing "+value);}
 void tap(String value)throws Exception{AccessibilityNodeInfo n=node(value,10000);Rect r=new Rect();n.getBoundsInScreen(r);check(n.isEnabled(),"Disabled "+value);n.recycle();long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,r.centerX(),r.centerY(),0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(ui.injectInputEvent(e,false),"Touch failed");e.recycle();Thread.sleep(40);}Thread.sleep(100);}
 void absent(String text)throws Exception{try{node(text,100).recycle();throw new AssertionError("Still blocks foreground: "+text);}catch(AssertionError e){if(e.getMessage().startsWith("Still blocks"))throw e;}}
 void open(String value)throws Exception{c.startActivity(new Intent(c,FloatingShareActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra(Intent.EXTRA_TEXT,value).putExtra("selected_collection","photo"));node(value,5000).recycle();node("保存到知识库",1000).recycle();}
 void pending()throws Exception{c.startActivity(new Intent(c,CapturePendingActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));node("返回",5000).recycle();}
 JSONObject waitRequests(int count)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){JSONObject result=control("");if(result.getJSONArray("requests").length()>=count)return result;Thread.sleep(100);}throw new AssertionError("Submission never reached fixture");}
 void shot(String name)throws Exception{Bitmap image=ui.takeScreenshot();try(OutputStream out=c.openFileOutput("submit-"+name+".png",0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 void report(String text){Bundle b=new Bundle();b.putString("stream","\n"+text+"\n");test.sendStatus(0,b);}
 void run(){Bundle result=new Bundle();try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Disposable emulator only");c.getSharedPreferences("MainActivity",0).edit().clear().putString("origin","http://10.0.2.2:3751").commit();c.getSharedPreferences("CaptureAuthorization",0).edit().putString(android.net.Uri.encode("http://10.0.2.2:3751"),"zn_"+"d".repeat(64)).commit();shell("settings delete secure enabled_accessibility_services");Thread.sleep(300);c.getSharedPreferences("CaptureAssist",0).edit().putBoolean("capture_bubble",true).commit();shell("settings put secure enabled_accessibility_services io.github.borderarea01.znote/.CaptureAssistService");shell("settings put secure accessibility_enabled 1");Thread.sleep(900);shell("am start -W -n org.example.reader/io.github.borderarea01.capturefixture.PageActivity --ez continueBrowsing true");
  control("hang");open("https://example.test/background-one");tap("刷新知识库列表");node("知识库列表已更新",14000).recycle();tap("摄影参考");tap("建模学习");tap("图片组 · 正文存备注");tap("图文笔记 · 配图成组");long start=SystemClock.uptimeMillis();tap("保存到知识库");node("继续浏览",1500).recycle();check(SystemClock.uptimeMillis()-start<1500,"Form waited for POST before closing");absent("保存到知识库");tap("继续浏览");node("已继续浏览",1000).recycle();JSONObject first=waitRequests(1);check(first.getInt("held")==1,"Test response must still be held");JSONObject input=first.getJSONArray("requests").getJSONObject(0);check(input.getString("collection_id").equals("models")&&input.getString("image_mode").equals("note"),"Confirmed target/mode lost");shot("browse-during-submit");
  open("https://example.test/new-form-kept");control("release");Thread.sleep(1200);node("https://example.test/new-form-kept",1500).recycle();tap("收起采集面板");report("Held POST closes before response; browsing touch works; old response preserves new form");
  control("lost");open("https://example.test/lost-response");tap("保存到知识库");absent("保存到知识库");waitRequests(2);Thread.sleep(800);pending();node("提交未完成",10000).recycle();node("https://example.test/lost-response",1000).recycle();shot("failed-retained");String request=control("").getJSONArray("requests").getJSONObject(1).getString("request_id");control("online");tap("重试提交");waitRequests(3);node("暂无待提交任务",10000).recycle();JSONObject retry=control("");check(retry.getInt("jobs")==2,"Retry duplicated server work");check(retry.getJSONArray("requests").getJSONObject(2).getString("request_id").equals(request),"Retry changed request ID");tap("返回");
  control("hang");open("https://example.test/restart-held");tap("保存到知识库");waitRequests(4);String pid=shell("pidof "+c.getPackageName()+":capture").trim();check(pid.matches("[0-9]+"),"Capture PID missing");shell("run-as "+c.getPackageName()+" kill "+pid);Thread.sleep(1200);pending();node("提交未完成",8000).recycle();node("https://example.test/restart-held",1000).recycle();check(control("").getJSONArray("requests").length()==4,"Interrupted write auto replayed");control("online");tap("重试提交");waitRequests(5);node("暂无待提交任务",12000).recycle();JSONObject restored=control("");check(restored.getInt("jobs")==3,"Restart retry duplicated work");check(restored.getJSONArray("requests").getJSONObject(3).getString("request_id").equals(restored.getJSONArray("requests").getJSONObject(4).getString("request_id")),"Restart lost stable ID");tap("返回");
  control("unavailable");open("https://example.test/fail-503");tap("保存到知识库");waitRequests(6);pending();node("提交未完成",10000).recycle();node("测试服务器暂时不可用",1000).recycle();tap("移除任务");tap("取消");node("https://example.test/fail-503",1000).recycle();tap("移除任务");tap("移除");node("暂无待提交任务",5000).recycle();shot("empty");tap("返回");
  // Keep the worker occupied so this UI test never calls a public Pixiv server.
  control("hang");open("https://example.test/queue-blocker");tap("保存到知识库");waitRequests(7);open("https://www.pixiv.net/artworks/12345");start=SystemClock.uptimeMillis();tap("保存到知识库");check(SystemClock.uptimeMillis()-start<1500,"Queued Pixiv lookup blocked UI");absent("保存到知识库");pending();node("https://www.pixiv.net/artworks/12345",3000).recycle();check(control("").getJSONArray("requests").length()==7,"Queued Pixiv bypassed background owner");shot("pixiv-queued");report("Lost response stable-ID retry, interrupted process recovery, 503/remove and queued Pixiv UI handoff passed");result.putString("stream","\nZNOTE_BACKGROUND_SUBMIT_PASS\n");test.finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{shot("failure");}catch(Exception ignored){}result.putString("stream","\nZNOTE_BACKGROUND_SUBMIT_FAIL: "+e+"\n");test.finish(Activity.RESULT_CANCELED,result);}}
}
